         '<path d="M64 90 C64 62 80 50 100 50 C120 50 136 62 136 90 C136 108 133 122 126 130 C118 138 110 140 100 140 C90 140 82 138 74 130 C67 122 64 108 64 90Z" fill="'+skin+'"/>';
